head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07407";
scwin.SCREN_PROCS_TP_CD_01 = "01";  // 조회 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.lastJob = "";  // 업무 처리명(confirmJob 이 채우고 alertJobResult 가 읽는다 — as-is 전역 LastJob)
scwin.vBzProcsNo = "";
scwin.vListBzTpCd = "";
scwin.clickListBzDtlTpCd = "";
scwin.clickAdjReqProcsNo = "";
scwin.dts_List = null;
scwin.pMenuID = undefined;
scwin.fr_MktId = undefined;
scwin.fn_trs = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Provider
    try {
        const parentWin = $c.win.getParent();
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vListBzTpCd = "210";
        await scwin.listSync();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07407.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.pMenuID =$c.win.getProgramId(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07407' }); }

try { scwin.fr_MktId =scwin.getMktId(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07407' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        scwin.fn_trs = scwin.sbm_trs_Save;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07407.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_List_ondblclick
 * @description grd_List 더블클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_ondblclick = async function (row, colid) {
    try {
        scwin.setBzProcsNo(row);
        if ("FUNC_ACPT" === colid) {
            let vAnswer = await $c.win.confirm('승인처리 하시겠습니까?');
            if (vAnswer === true) {
                scwin.lastJob = "승인";
                scwin.fn_trs("35");
            }
        } else {
            if ("FUNC_RJCT" === colid) {
                vAnswer = await $c.win.confirm('불가처리 하시겠습니까?');
                if (vAnswer === true) {
                    scwin.lastJob = "불가";
                    scwin.fn_trs("36");
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07407.grd_List_ondblclick' }); }
};

/**
 * @method
 * @name dts_List_onloadcompleted
 * @description dts_List onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_onloadcompleted = function (rowcount) {
    try {
        void 0;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07407.dts_List_onloadcompleted" });
    }
};

/**
 * @method
 * @name dts_List_onloaderror
 * @description dts_List onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07407.dts_List_onloaderror" });
    }
};

/**
 * @method
 * @name trs_Save_onfail
 * @description trs_Save onfail 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onfail = async function () {
    try {
        await scwin.alertJobResult('F');
        $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07407.trs_Save_onfail" });
    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description trs_Save onsuccess 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        await scwin.alertJobResult('S');
        await scwin.listSync();
        scwin.parentRefresh();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07407.trs_Save_onsuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07407.btn_Close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_List
 * @description script dts List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_List = async function () {
    $c.util.getComponent("dma_scriptDts_ListReq").set("SCREN_ID", "ULDSTF07407.gfm");
    $c.util.getComponent("dma_scriptDts_ListReq").set("BZ_PROCS_NO", "");
    $c.util.getComponent("dma_scriptDts_ListReq").set("LIST_INVSTG_BZ_TP_CD", "");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD", unresolved: "query_param:SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_List",
        method: "post",
        action: "/lstinvstg/LstInvstgCommon.do",
        ref: "dma_scriptDts_ListReq",
        target: "dts_List=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_List_onloaderror'] === 'function') ? scwin['dts_List_onloaderror'] : (typeof scwin['dts_List_onfail'] === 'function') ? scwin['dts_List_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_List_onloadcompleted'] === 'function') ? scwin['dts_List_onloadcompleted'] : ((typeof scwin['dts_List_onsuccess'] === 'function') ? scwin['dts_List_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_List'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07407.tx_script_dts_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name sbm_trs_Save
 * @description trs Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_trs_Save = async function () {
    const sbmOptions = {
        id: "sbm_trs_Save",
        method: "post",
        action: "/lstinvstg/KsqSkilValu.do",
        ref: "dma_sbmTrs_SaveReq",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['trs_Save_onloaderror'] === 'function') ? scwin['trs_Save_onloaderror'] : (typeof scwin['trs_Save_onfail'] === 'function') ? scwin['trs_Save_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['trs_Save_onloadcompleted'] === 'function') ? scwin['trs_Save_onloadcompleted'] : ((typeof scwin['trs_Save_onsuccess'] === 'function') ? scwin['trs_Save_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('trs_Save'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07407.sbm_trs_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function () {
    let url = "/lstinvstg/LstInvstgCommon.do?SCREN_ID=" + "ULDSTF07407.gfm" + "&SCREN_PROCES_TP_CD=" + scwin.SCREN_PROCS_TP_CD_01 + "&method=listAdjReq";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&LIST_INVSTG_BZ_TP_CD=" + scwin.vListBzTpCd;

    await scwin.tx_script_dts_List();
    void 0;
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function (obj) {
    scwin.clickListBzDtlTpCd = scwin.dts_List.getCellData((obj), "LIST_BZ_DTL_TP_CD");
    scwin.clickAdjReqProcsNo = scwin.dts_List.getCellData((obj), "ADJ_REQ_PROCS_NO");
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Provider
    const fr_fn_list_sync = $c.win.getParent().fn_list_sync;
    fr_fn_list_sync();
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name getMktId
 * @description 시장 ID — as-is 전역 js_market(서버가 렌더 때 넣던 값)을 읽는다
 * @returns {String} 시장 ID(없으면 빈 문자열)
 * @hidden N
 */
scwin.getMktId = function () {
    // TODO Stage2: 컨텍스트 키 출처 미확인(as-is 전역 js_market · 회신 A-3) — 서버 응답/세션에서 받도록 연결
    return (typeof js_market !== "undefined" && js_market != null) ? String(js_market) : "";
};

/**
 * @method
 * @name alertJobResult
 * @description 업무 처리 결과 알림 — S "[처리명] 처리 성공하였습니다." · S1 "성공적으로 처리되었습니다." · F "[처리명] 처리 실패하였습니다."
 * @param {*} gubun 결과 구분(S 성공 · S1 성공(처리명 없음) · F 실패)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertJobResult = async function (gubun) {
    const job = scwin.lastJob || "";
    if (gubun === "S") { await $c.win.alert("[" + job + "] 처리 성공하였습니다."); }
    else if (gubun === "S1") { await $c.win.alert("성공적으로 처리되었습니다."); }
    else if (gubun === "F") { await $c.win.alert("[" + job + "] 처리 실패하였습니다."); }
};
